"""
pseofactory.edge: Centralized Edge Infrastructure & Standards.
Provides centralized Cloudflare Pages edge headers builder,
host configuration hygiene auditing, and edge header validation.
Zero em-dashes. Zero en-dashes.
"""

import json
import shutil
from pathlib import Path
import re
from typing import Any, Dict, List, Optional, Set, Tuple, Union
import urllib.parse
from dataclasses import dataclass, field

from pseofactory.contracts import assert_no_forbidden_dashes
from pseofactory.lead_classification import edge_classifier_json
from pseofactory.affiliate_intent import (
    BLOCKED_SOVRN_FALLBACK_KEYS,
    filter_intent_matched_contracts,
    is_intent_matched,
)


class EdgeConfigStandards:
    """Standardized edge caching directives and machine content types."""

    MAX_CLOUDFLARE_HEADERS_RULES: int = 95
    MAX_CLOUDFLARE_REDIRECTS_RULES: int = 95
    STATIC_CACHE: str = "public, max-age=31536000, immutable"
    HTML_MACHINE_CACHE: str = "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800"
    CRAWLER_AND_FEED_CACHE: str = "public, max-age=0, s-maxage=60, must-revalidate"
    ERROR_CACHE: str = "no-store"
    SECURITY_HEADERS: Dict[str, str] = {
        "X-Content-Type-Options": "nosniff",
        "X-Frame-Options": "SAMEORIGIN",
        "Referrer-Policy": "strict-origin-when-cross-origin",
    }
    MACHINE_CONTENT_TYPES: Dict[str, str] = {
        ".xml": "application/xml; charset=utf-8",
        ".txt": "text/plain; charset=utf-8",
        ".json": "application/json; charset=utf-8",
    }
    STATIC_FUNCTION_BYPASS_EXCLUDES: List[str] = [
        "/static/*",
        "/videos/*",
        "/manifests/*",
        "/*.css",
        "/*.js",
        "/*.mp4",
        "/*.vtt",
        "/*.xml",
        "/*.txt",
        "/*.json",
        "/*.ico",
        "/*.png",
        "/*.svg",
        "/*.webp",
        "/*.woff2",
    ]


def build_edge_routes_json(
    include: Optional[List[str]] = None,
    exclude: Optional[List[str]] = None,
) -> str:
    """
    Builds deterministic Cloudflare Pages dist/_routes.json configuration so static assets,
    stylesheets, scripts, videos, sitemaps, and machine manifests bypass Pages Functions
    invocations (preserving the 100,000/day Free Tier invocation quota for HTML middleware,
    /api/*, and /r/* routes).
    """
    payload = {
        "version": 1,
        "include": include if include is not None else ["/*"],
        "exclude": exclude if exclude is not None else list(EdgeConfigStandards.STATIC_FUNCTION_BYPASS_EXCLUDES),
    }
    content = json.dumps(payload, indent=2) + "\n"
    assert_no_forbidden_dashes(content, "build_edge_routes_json")
    return content


def build_edge_headers(
    canonical_base: str,
    routes: Optional[List[str]] = None,
    machine_endpoints: Optional[List[str]] = None,
    static_patterns: Optional[List[str]] = None,
    custom_headers: Optional[Dict[str, List[str]]] = None,
    max_active_rules: int = EdgeConfigStandards.MAX_CLOUDFLARE_HEADERS_RULES,
) -> str:
    """
    Builds standard Cloudflare Pages dist/_headers syntax.
    Enforces immutable static asset caching, edge s-maxage and stale-while-revalidate
    on root HTML, RFC 5988 canonical Link headers, and UTF-8 machine content types.
    Caps active Cloudflare Pages header rules at max_active_rules (<= 95, under
    Cloudflare Pages' 100-rule limit) while preserving overflow leaf canonical entries
    for edge middleware and SEO verification parity.
    Strictly forbids noindex or nosnippet on public routes.
    """
    base = canonical_base.rstrip("/")
    lines: List[str] = [
        "# Cloudflare Pages Edge Headers generated by pseofactory.edge",
    ]
    active_rules_count = 0
    seen_routes: Set[str] = set()

    # 1. Static asset cache policies
    patterns = static_patterns if static_patterns is not None else [
        "/static/css/*",
        "/static/js/*",
        "/static/*",
        "/css/*",
        "/js/*",
        "/assets/*",
    ]
    for pattern in patterns:
        if pattern in seen_routes:
            continue
        seen_routes.add(pattern)
        lines.append(pattern)
        lines.append(f"  Cache-Control: {EdgeConfigStandards.STATIC_CACHE}")
        lines.append("")
        active_rules_count += 1

    # 2. Root HTML fallback and security headers
    seen_routes.add("/*")
    lines.append("/*")
    lines.append(f"  Cache-Control: {EdgeConfigStandards.HTML_MACHINE_CACHE}")
    for sec_header, sec_val in EdgeConfigStandards.SECURITY_HEADERS.items():
        lines.append(f"  {sec_header}: {sec_val}")
    lines.append("")
    active_rules_count += 1

    # 3. 404 Error page cache policy
    seen_routes.add("/404.html")
    lines.append("/404.html")
    lines.append(f"  Cache-Control: {EdgeConfigStandards.ERROR_CACHE}")
    lines.append("")
    active_rules_count += 1

    # 4. Machine endpoints (RFC 5988 canonical link and UTF-8 charset content-type)
    raw_endpoints = list(
        machine_endpoints
        if machine_endpoints is not None
        else [
            "/robots.txt",
            "/feed.xml",
            "/llms.txt",
            "/llms-full.txt",
            "/catalog.json",
            "/media-kit.json",
            "/sitemap.xml",
            "/sitemap-hubs.xml",
            "/sitemap-leaves.xml",
        ]
    )
    for required_ep in ("/robots.txt", "/catalog.json", "/media-kit.json"):
        if required_ep not in raw_endpoints and required_ep.lstrip("/") not in raw_endpoints:
            raw_endpoints.append(required_ep)

    fresh_revalidate_endpoints: Set[str] = {
        "/robots.txt",
        "/sitemap.xml",
        "/sitemap-hubs.xml",
        "/sitemap-leaves.xml",
        "/feed.xml",
        "/llms.txt",
        "/llms-full.txt",
    }

    for ep in raw_endpoints:
        path = ep if ep.startswith("/") else f"/{ep}"
        if path in seen_routes:
            continue
        seen_routes.add(path)
        lines.append(path)
        lines.append(f'  Link: <{base}{path}>; rel="canonical"')
        ext = Path(path).suffix.lower()
        if ext in EdgeConfigStandards.MACHINE_CONTENT_TYPES:
            ct = EdgeConfigStandards.MACHINE_CONTENT_TYPES[ext]
            lines.append(f"  Content-Type: {ct}")
        if path in fresh_revalidate_endpoints:
            lines.append(f"  Cache-Control: {EdgeConfigStandards.CRAWLER_AND_FEED_CACHE}")
        elif path in ("/catalog.json", "/media-kit.json"):
            lines.append(f"  Cache-Control: {EdgeConfigStandards.HTML_MACHINE_CACHE}")
            lines.append("  X-Robots-Tag: index, follow")
        lines.append("")
        active_rules_count += 1

    if "/ai-benchmarks/*" not in seen_routes and active_rules_count < max_active_rules:
        seen_routes.add("/ai-benchmarks/*")
        lines.append("/ai-benchmarks/*")
        lines.append(f"  Cache-Control: {EdgeConfigStandards.CRAWLER_AND_FEED_CACHE}")
        lines.append("")
        active_rules_count += 1

    # 5. Custom headers (prioritized before bulk HTML routes)
    if custom_headers:
        for route_key, header_list in custom_headers.items():
            path = route_key if route_key.startswith("/") else f"/{route_key}"
            if path in seen_routes:
                continue
            seen_routes.add(path)
            lines.append(path)
            for h in header_list:
                lines.append(f"  {h}")
            lines.append("")
            active_rules_count += 1

    # 6. Public HTML routes (RFC 5988 canonical link), prioritizing root and hub routes
    if routes:
        normalized_routes: List[str] = []
        for r in routes:
            path = r if r.startswith("/") else f"/{r}"
            if path not in seen_routes:
                seen_routes.add(path)
                normalized_routes.append(path)

        def _route_priority(p: str) -> Tuple[int, int]:
            segments = [s for s in p.strip("/").split("/") if s]
            # Priority 0: root & top-level pages (/, /about/, /tools/, etc.)
            # Priority 1: calculator hubs (/tools/<slug>/)
            # Priority 2: programmatic leaf routes (/tools/<slug>/<leaf>/)
            depth_tier = 0 if len(segments) <= 1 else (1 if len(segments) == 2 else 2)
            return (depth_tier, len(segments))

        prioritized_routes = [
            p for _, p in sorted(enumerate(normalized_routes), key=lambda item: (_route_priority(item[1]), item[0]))
        ]
        for path in prioritized_routes:
            if active_rules_count < max_active_rules:
                lines.append(path)
                lines.append(f'  Link: <{base}{path}>; rel="canonical"')
                lines.append("")
                active_rules_count += 1
            else:
                lines.append(f"# [edge-middleware-canonical] {path}")
                lines.append(f'#   Link: <{base}{path}>; rel="canonical"')
                lines.append("")

    content = "\n".join(lines).rstrip() + "\n"

    # Validate against snippet policy if contracts available
    try:
        from pseofactory.contracts import assert_headers_snippet_policy
        assert_headers_snippet_policy(content, context="build_edge_headers")
    except ImportError:
        pass

    return content


def compact_edge_headers_to_cloudflare_cap(
    content: str,
    max_active_rules: int = EdgeConfigStandards.MAX_CLOUDFLARE_HEADERS_RULES,
) -> str:
    """
    Compacts an existing dist/_headers file so active non-comment route blocks never exceed
    max_active_rules (<= 95, safely below Cloudflare Pages' 100-rule limit).
    Prioritizes static assets, root /*, /404.html, machine endpoints (.xml, .txt, .json),
    and top-level/hub routes in active blocks, and converts excess leaf blocks into
    # [edge-middleware-canonical] declarations served dynamically at the edge.
    """
    blocks: List[Tuple[str, List[str], bool]] = []
    cur_route: Optional[str] = None
    cur_hdrs: List[str] = []
    cur_is_comment = False

    def _flush() -> None:
        nonlocal cur_route, cur_hdrs, cur_is_comment
        if cur_route and cur_hdrs:
            blocks.append((cur_route, list(cur_hdrs), cur_is_comment))
        cur_route = None
        cur_hdrs = []
        cur_is_comment = False

    for raw_line in content.splitlines():
        stripped = raw_line.strip()
        if not stripped:
            continue
        if stripped.startswith("# [edge-middleware-canonical] "):
            _flush()
            cur_route = stripped.split("# [edge-middleware-canonical]", 1)[1].strip()
            cur_is_comment = True
            continue
        if cur_is_comment and stripped.startswith("#") and "Link:" in stripped:
            hdr_part = stripped.lstrip("#").strip()
            cur_hdrs.append(hdr_part)
            continue
        if stripped.startswith("#"):
            continue
        if not raw_line.startswith(" ") and not raw_line.startswith("\t"):
            _flush()
            cur_route = stripped
            cur_is_comment = False
        elif cur_route is not None:
            cur_hdrs.append(stripped)
    _flush()

    if not blocks:
        return content

    # Deduplicate by route preserving merged headers (e.g. if /catalog.json was appended later)
    merged: Dict[str, List[str]] = {}
    order: List[str] = []
    for route, hdrs, _ in blocks:
        if route not in merged:
            merged[route] = []
            order.append(route)
        for h in hdrs:
            if h not in merged[route]:
                merged[route].append(h)

    def _block_priority(route: str) -> Tuple[int, int]:
        if any(pat in route for pat in ("/static", "/css", "/js", "/assets")):
            return (0, 0)
        if route in ("/*", "/404.html"):
            return (1, 0)
        if route.endswith((".xml", ".txt", ".json")) or route == "/ai-benchmarks/*":
            return (2, 0)
        segments = [s for s in route.strip("/").split("/") if s]
        if len(segments) <= 1:
            return (3, len(segments))
        if len(segments) == 2:
            return (4, len(segments))
        return (5, len(segments))

    sorted_routes = [
        r for _, r in sorted(enumerate(order), key=lambda item: (_block_priority(item[1]), item[0]))
    ]
    out_lines: List[str] = [
        "# Cloudflare Pages Edge Headers generated by pseofactory.edge",
    ]
    active_count = 0
    for route in sorted_routes:
        hdrs = merged[route]
        if active_count < max_active_rules:
            out_lines.append(route)
            for h in hdrs:
                out_lines.append(f"  {h}")
            out_lines.append("")
            active_count += 1
        else:
            out_lines.append(f"# [edge-middleware-canonical] {route}")
            for h in hdrs:
                out_lines.append(f"#   {h}")
            out_lines.append("")

    return "\n".join(out_lines).rstrip() + "\n"


_CROSS_LEGAL_GOVERNANCE_SOURCES: Set[str] = {
    "/methodology",
    "/methodology/",
    "/about",
    "/about/",
    "/privacy",
    "/privacy/",
    "/disclaimers",
    "/disclaimers/",
    "/terms",
    "/terms/",
    "/contact",
    "/contact/",
}

_GOVERNANCE_REDIRECT_SOURCES: Set[str] = {
    "/methodology",
    "/methodology/",
    "/about",
    "/about/",
    "/privacy",
    "/privacy/",
    "/disclaimers",
    "/disclaimers/",
    "/terms",
    "/terms/",
    "/contact",
    "/contact/",
    "/terms-of-service",
    "/terms-of-service/",
    "/privacy-policy",
    "/privacy-policy/",
}


def parse_edge_redirects_rules(
    content: str,
    include_middleware_overflow: bool = True,
) -> List[Tuple[str, str, str, bool]]:
    """
    Parses Cloudflare Pages _redirects rules into (src, dst, status_code, is_overflow).
    Supports both active rule lines and '# [edge-middleware-redirect] <src> <dst> <code'
    overflow lines handled by functions/_middleware.js.
    """
    parsed: List[Tuple[str, str, str, bool]] = []
    for raw_line in content.splitlines():
        stripped = raw_line.strip()
        if not stripped:
            continue
        is_overflow = False
        if stripped.startswith("# [edge-middleware-redirect]"):
            if not include_middleware_overflow:
                continue
            stripped = stripped[len("# [edge-middleware-redirect]") :].strip()
            is_overflow = True
        elif stripped.startswith("#"):
            continue
        parts = stripped.split()
        if len(parts) >= 2:
            src = parts[0].strip()
            dst = parts[1].strip()
            code = parts[2].strip() if len(parts) >= 3 else "301"
            parsed.append((src, dst, code, is_overflow))
    return parsed


def compact_edge_redirects_to_cloudflare_cap(
    content: str,
    max_active_rules: int = EdgeConfigStandards.MAX_CLOUDFLARE_REDIRECTS_RULES,
    existing_governance_routes: Optional[Set[str]] = None,
) -> str:
    """
    Compacts an existing dist/_redirects file so active non-comment rule lines never exceed
    max_active_rules (<= 95, safely under Cloudflare Pages' hard 100-rule limit).
    Prioritizes:
      0. Governance routes (/methodology, /about, /privacy, /disclaimers, /terms, etc.)
      1. Wildcard/splat rules and /vs/ordermetrics* rules
      2. Canonical slashless base paths (/tools/foo)
      3. Trailing-slash duplicate paths (/tools/foo/)
    Overflow rules beyond max_active_rules are preserved as '# [edge-middleware-redirect]'
    annotations and served with HTTP 301 at the edge by functions/_middleware.js.
    """
    parsed = parse_edge_redirects_rules(content, include_middleware_overflow=True)
    if not parsed:
        return content

    deduped: Dict[str, Tuple[str, str]] = {}
    order: List[str] = []
    for src, dst, code, _is_ov in parsed:
        if not src.startswith("/"):
            continue
        if (
            existing_governance_routes
            and src in _CROSS_LEGAL_GOVERNANCE_SOURCES
            and src.strip("/") in existing_governance_routes
        ):
            continue
        if src not in deduped:
            deduped[src] = (dst, code)
            order.append(src)

    if not order:
        return content

    def _redirect_priority(src_path: str) -> int:
        if src_path in _GOVERNANCE_REDIRECT_SOURCES:
            return 0
        if "*" in src_path or ":" in src_path or src_path.startswith("/vs/ordermetrics"):
            return 1
        if src_path != "/" and not src_path.endswith("/"):
            return 2
        return 3

    sorted_sources = [
        s for _, s in sorted(enumerate(order), key=lambda item: (_redirect_priority(item[1]), item[0]))
    ]
    out_lines: List[str] = []
    active_count = 0
    for src in sorted_sources:
        dst, code = deduped[src]
        if active_count < max_active_rules:
            out_lines.append(f"{src}  {dst}  {code}")
            active_count += 1
        else:
            out_lines.append(f"# [edge-middleware-redirect] {src}  {dst}  {code}")

    result = "\n".join(out_lines).rstrip() + "\n"
    assert_no_forbidden_dashes(result, "compact_edge_redirects_to_cloudflare_cap")
    return result


def validate_edge_redirects_file(
    redirects_path: Union[str, Path],
    max_active_rules: int = EdgeConfigStandards.MAX_CLOUDFLARE_REDIRECTS_RULES,
) -> Dict[str, Any]:
    """
    Validates compiled dist/_redirects against Cloudflare Pages' 100-rule truncation limit
    (enforcing <= max_active_rules active non-comment rules) and checks basic rule syntax.
    """
    rp = Path(redirects_path)
    issues: List[str] = []
    if not rp.is_file():
        return {
            "status": "FAIL",
            "redirects_path": str(rp),
            "active_rules_count": 0,
            "total_rules_count": 0,
            "violations_count": 1,
            "issues": [f"Redirects file not found: {rp}"],
        }
    content = rp.read_text(encoding="utf-8", errors="ignore")
    active_rules = parse_edge_redirects_rules(content, include_middleware_overflow=False)
    all_rules = parse_edge_redirects_rules(content, include_middleware_overflow=True)
    if len(active_rules) > max_active_rules:
        issues.append(
            f"Active _redirects rule count ({len(active_rules)}) exceeds Cloudflare Pages cap ({max_active_rules})"
        )
    all_sources = {src for src, _dst, _code, _ov in all_rules}
    for src, dst, _code, _ov in all_rules:
        if src != "/" and src.rstrip("/") == dst.rstrip("/"):
            issues.append(f"Self-redirect detected in _redirects: {src} -> {dst}")
        elif dst != "/" and dst in all_sources:
            issues.append(f"Redirect chain detected in _redirects: {src} -> {dst}")
    return {
        "status": "PASS" if not issues else "FAIL",
        "redirects_path": str(rp),
        "active_rules_count": len(active_rules),
        "total_rules_count": len(all_rules),
        "violations_count": len(issues),
        "issues": issues,
    }


def _collect_tenant_middleware_redirects(
    repo: Path,
    dist_dir: Path,
) -> Tuple[Dict[str, str], Dict[str, str]]:
    """
    Collects exact 301 redirect rules and wildcard splat prefix rules from
    content/redirects.json and dist/_redirects so functions/_middleware.js
    handles both exact and prefix rules with full specificity parity.
    """
    exact_redirects: Dict[str, str] = {}
    prefix_redirects: Dict[str, str] = {}
    content_redirects_json = repo / "content" / "redirects.json"
    if content_redirects_json.is_file():
        try:
            raw_rj = json.loads(content_redirects_json.read_text(encoding="utf-8"))
            if isinstance(raw_rj, dict):
                for r_src, r_info in raw_rj.items():
                    r_dst = r_info.get("target") if isinstance(r_info, dict) else r_info
                    r_code = int(r_info.get("status", 301)) if isinstance(r_info, dict) else 301
                    if (
                        isinstance(r_src, str)
                        and isinstance(r_dst, str)
                        and r_code in (301, 302, 307, 308)
                        and r_src.startswith("/")
                        and "*" not in r_src
                        and ":" not in r_src
                    ):
                        base_src = r_src.rstrip("/")
                        if base_src and not (dist_dir / base_src.lstrip("/") / "index.html").is_file():
                            exact_redirects[base_src] = r_dst
                            exact_redirects[base_src + "/"] = r_dst
        except Exception:
            pass

    dist_redirects_file = dist_dir / "_redirects"
    parsed_rules: List[Tuple[str, str, str, bool]] = []
    if dist_redirects_file.is_file():
        try:
            parsed_rules = parse_edge_redirects_rules(
                dist_redirects_file.read_text(encoding="utf-8", errors="ignore"),
                include_middleware_overflow=True,
            )
        except Exception:
            parsed_rules = []

    for r_src, r_dst, r_code_str, _is_ov in parsed_rules:
        if (
            r_code_str in ("301", "302", "307", "308")
            and r_src.startswith("/")
            and "*" not in r_src
            and ":" not in r_src
            and r_src != "/"
        ):
            base_src = r_src.rstrip("/")
            if base_src and not (dist_dir / base_src.lstrip("/") / "index.html").is_file():
                exact_redirects[base_src] = r_dst
                exact_redirects[base_src + "/"] = r_dst

    for r_src, r_dst, r_code_str, _is_ov in parsed_rules:
        if (
            r_code_str in ("301", "302", "307", "308")
            and r_src.startswith("/")
            and r_src.endswith("/*")
            and "*" not in r_src[:-2]
            and ":" not in r_src
            and r_src != "/*"
        ):
            prefix_key = r_src[:-1]
            prefix_redirects[prefix_key] = r_dst
            base_prefix = prefix_key.rstrip("/")
            if (
                base_prefix
                and base_prefix not in exact_redirects
                and not (dist_dir / base_prefix.lstrip("/") / "index.html").is_file()
            ):
                exact_redirects[base_prefix] = r_dst
                exact_redirects[base_prefix + "/"] = r_dst

    return exact_redirects, prefix_redirects


def _sync_middleware_redirect_table(
    mw_text: str,
    extra_exact_redirects: Dict[str, str],
    extra_prefix_redirects: Optional[Dict[str, str]] = None,
    apex_domain: Optional[str] = None,
    existing_governance_routes: Optional[Set[str]] = None,
) -> str:
    """
    Synchronizes exact and prefix 301 redirect mappings into functions/_middleware.js,
    sorting prefix rules longest-first, preserving query strings, and resolving redirects
    prior to www-to-apex canonicalization so legacy www URLs redirect in a single 301 hop.
    """
    eff_apex = apex_domain
    if not eff_apex:
        apex_m = re.search(r'hostname === "(?:www\.)?([a-z0-9.-]+\.[a-z]{2,})"', mw_text)
        if apex_m:
            eff_apex = apex_m.group(1)

    working = mw_text
    if eff_apex:
        early_www_pat = re.compile(
            rf'\n*  if \(hostname === "www\.{re.escape(eff_apex)}"\) \{{\n'
            rf'    return Response\.redirect\(`https://{re.escape(eff_apex)}\$\{{pathname\}}\$\{{url\.search\}}`, 301\);\n'
            rf'  \}}\n*'
        )
        probe_m = re.search(r"  const (legacySaaSRedirects|edgeRedirects) = \{\n", working)
        if probe_m:
            working = early_www_pat.sub("\n\n", working[: probe_m.start()]) + working[probe_m.start() :]

    prefix_pair_pat = re.compile(r'\[\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\]')
    merged_prefixes: Dict[str, str] = {}
    prefix_order: List[str] = []
    for pm in re.finditer(r"const legacyPrefixTargets = \[([\s\S]*?)\];", working):
        for pair_m in prefix_pair_pat.finditer(pm.group(1)):
            pk, pv = pair_m.group(1), pair_m.group(2)
            norm_pk = pk if pk.endswith("/") else pk + "/"
            if norm_pk not in merged_prefixes:
                prefix_order.append(norm_pk)
            merged_prefixes[norm_pk] = pv
    for pk, pv in (extra_prefix_redirects or {}).items():
        if not pk.startswith("/"):
            continue
        norm_pk = pk if pk.endswith("/") else pk + "/"
        if norm_pk not in merged_prefixes:
            prefix_order.append(norm_pk)
        merged_prefixes[norm_pk] = pv
    sorted_prefixes = [
        pk for _, pk in sorted(enumerate(prefix_order), key=lambda item: (-len(item[1]), item[0]))
    ]

    obj_match = re.search(
        r"(  const (legacySaaSRedirects|edgeRedirects) = \{\n)([\s\S]*?)(  \};)",
        working,
    )
    if not obj_match:
        return mw_text

    var_name = obj_match.group(2)
    body_text = obj_match.group(3)
    entry_pat = re.compile(r'^\s*"([^"]+)"\s*:\s*"([^"]+)"\s*,?\s*$')
    merged_entries: Dict[str, str] = {}
    entry_order: List[str] = []
    for raw_line in body_text.splitlines():
        em = entry_pat.match(raw_line)
        if em:
            k, v = em.group(1), em.group(2)
            if (
                existing_governance_routes
                and k in _CROSS_LEGAL_GOVERNANCE_SOURCES
                and k.strip("/") in existing_governance_routes
            ):
                continue
            if existing_governance_routes and v.rstrip("/") == "/disclaimers" and "disclaimers" not in existing_governance_routes:
                if "privacy" in k and "privacy" in existing_governance_routes:
                    v = "/privacy/"
                elif "terms" in existing_governance_routes:
                    v = "/terms/"
            if k not in merged_entries:
                entry_order.append(k)
            merged_entries[k] = v

    for k, v in extra_exact_redirects.items():
        if not k.startswith("/") or "*" in k or ":" in k or k == "/":
            continue
        if (
            existing_governance_routes
            and k in _CROSS_LEGAL_GOVERNANCE_SOURCES
            and k.strip("/") in existing_governance_routes
        ):
            continue
        if existing_governance_routes and v.rstrip("/") == "/disclaimers" and "disclaimers" not in existing_governance_routes:
            if "privacy" in k and "privacy" in existing_governance_routes:
                v = "/privacy/"
            elif "terms" in existing_governance_routes:
                v = "/terms/"
        if k.rstrip("/") == v.rstrip("/"):
            continue
        if k not in merged_entries:
            entry_order.append(k)
        merged_entries[k] = v

    rendered_lines = [f'    "{k}": "{merged_entries[k]}",' for k in entry_order]
    new_obj_block = obj_match.group(1) + "\n".join(rendered_lines) + "\n" + obj_match.group(4)

    post_part = working[obj_match.end() :]
    post_part = re.sub(
        r"\n*  // \[BEGIN_EDGE_REDIRECT_DISPATCH\][\s\S]*?  // \[END_EDGE_REDIRECT_DISPATCH\]\n*",
        "\n",
        post_part,
    )
    post_part = re.sub(
        r"\n*  const _normRedirectPath = [\s\S]*?  if \(_matchedRedirectTarget\) \{\n    return Response\.redirect\([^\n]+\);\n  \}\n*",
        "\n",
        post_part,
    )
    post_part = re.sub(
        rf"\n*  if \({re.escape(var_name)}\[pathname\]\) \{{\n    return Response\.redirect\([^\n]+\);\n  \}}\n*",
        "\n",
        post_part,
    )
    post_part = re.sub(
        r"\n*  const legacyPrefixTargets = \[[\s\S]*?\];\n  for \(const \[prefix, target\] of legacyPrefixTargets\) \{\n    if \(pathname\.startsWith\(prefix\)\) \{\n      return Response\.redirect\([^\n]+\);\n    \}\n  \}\n*",
        "\n",
        post_part,
    )

    origin_expr = (
        f'hostname === "www.{eff_apex}" ? "https://{eff_apex}" : url.origin'
        if eff_apex
        else "url.origin"
    )
    dispatch_lines = [
        "  // [BEGIN_EDGE_REDIRECT_DISPATCH]",
        f"  const _canonicalOrigin = {origin_expr};",
        '  const _normRedirectPath = pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;',
    ]
    if sorted_prefixes:
        dispatch_lines.append(
            f'  let _matchedRedirectTarget = {var_name}[pathname] || {var_name}[_normRedirectPath] || {var_name}[_normRedirectPath + "/"] || null;'
        )
        dispatch_lines.append("  if (!_matchedRedirectTarget) {")
        dispatch_lines.append("    const legacyPrefixTargets = [")
        for pk in sorted_prefixes:
            dispatch_lines.append(f'      ["{pk}", "{merged_prefixes[pk]}"],')
        dispatch_lines.extend(
            [
                "    ];",
                "    for (const [prefix, target] of legacyPrefixTargets) {",
                "      if (pathname.startsWith(prefix)) {",
                "        _matchedRedirectTarget = target;",
                "        break;",
                "      }",
                "    }",
                "  }",
            ]
        )
    else:
        dispatch_lines.append(
            f'  const _matchedRedirectTarget = {var_name}[pathname] || {var_name}[_normRedirectPath] || {var_name}[_normRedirectPath + "/"] || null;'
        )
    dispatch_lines.extend(
        [
            "  if (_matchedRedirectTarget) {",
            '    const _redirectQs = url.search.length > 1 ? (_matchedRedirectTarget.includes("?") ? "&" + url.search.slice(1) : url.search) : "";',
            '    const _destBase = _matchedRedirectTarget.startsWith("http") ? _matchedRedirectTarget : `${_canonicalOrigin}${_matchedRedirectTarget}`;',
            "    return Response.redirect(`${_destBase}${_redirectQs}`, 301);",
            "  }",
        ]
    )
    if eff_apex:
        dispatch_lines.extend(
            [
                f'  if (hostname === "www.{eff_apex}") {{',
                f"    return Response.redirect(`https://{eff_apex}${{pathname}}${{url.search}}`, 301);",
                "  }",
            ]
        )
    dispatch_lines.append("  // [END_EDGE_REDIRECT_DISPATCH]")

    dispatch_block = "\n".join(dispatch_lines)
    return working[: obj_match.start()] + new_obj_block + "\n\n" + dispatch_block + "\n\n" + post_part.lstrip("\n")


class HostHygieneAuditor:
    """Audits root deployment configuration files for crawler hygiene."""

    @classmethod
    def audit_repo_host_configs(cls, repo_path: Union[str, Path]) -> Dict[str, Any]:
        """
        Audits firebase.json, wrangler.toml, etc., in target repository.
        Catches blanket noindex directives and verifies cache retention policies.
        """
        repo = Path(repo_path)
        issues: List[str] = []
        configs_checked: List[str] = []

        if not repo.exists() or not repo.is_dir():
            return {
                "status": "FAIL",
                "repo_path": str(repo),
                "configs_checked": [],
                "violations_count": 1,
                "issues": [f"Repository path does not exist: {repo}"],
            }

        # 1. Audit firebase.json
        firebase_file = repo / "firebase.json"
        if firebase_file.is_file():
            configs_checked.append("firebase.json")
            try:
                data = json.loads(firebase_file.read_text(encoding="utf-8"))
                headers_rules = data.get("hosting", {}).get("headers", [])
                has_edge_cache = False

                for rule in headers_rules:
                    src = (rule.get("source") or "").strip()
                    for h in rule.get("headers", []):
                        k = (h.get("key") or "").strip().lower()
                        v = (h.get("value") or "").strip().lower()

                        # Detect blanket noindex / nofollow / noarchive on public wildcards
                        if src in ("**", "/*", "*") and k == "x-robots-tag":
                            if any(d in v for d in ["noindex", "nofollow", "noarchive"]):
                                issues.append(
                                    f"firebase.json contains lethal X-Robots-Tag directive '{v}' on wildcard '{src}'"
                                )

                        # Detect edge caching directives
                        if k == "cache-control":
                            if "s-maxage=86400" in v and "stale-while-revalidate=604800" in v:
                                has_edge_cache = True

                if not has_edge_cache:
                    issues.append(
                        "firebase.json missing s-maxage=86400 and stale-while-revalidate=604800 in cache headers"
                    )
            except Exception as e:
                issues.append(f"Failed to parse firebase.json: {e}")

        # 2. Audit wrangler.toml
        wrangler_file = repo / "wrangler.toml"
        if wrangler_file.is_file():
            configs_checked.append("wrangler.toml")
            try:
                wrangler_content = wrangler_file.read_text(encoding="utf-8")
                if "noindex" in wrangler_content.lower():
                    issues.append("wrangler.toml contains potential noindex directive")
            except Exception as e:
                issues.append(f"Failed to read wrangler.toml: {e}")

        return {
            "status": "PASS" if not issues else "FAIL",
            "repo_path": str(repo),
            "configs_checked": configs_checked,
            "violations_count": len(issues),
            "issues": issues,
        }

    def audit(self, repo_path: Union[str, Path]) -> Dict[str, Any]:
        """Instance method delegating to classmethod."""
        return self.audit_repo_host_configs(repo_path)


def validate_edge_headers_file(
    headers_path: Union[str, Path],
    enforce_rule_cap: bool = False,
) -> Dict[str, Any]:
    """
    Validates compiled dist/_headers file.
    Asserts presence of s-maxage, stale-while-revalidate, immutable static assets,
    RFC 5988 canonical links on machine endpoints, Cloudflare 100-rule cap compliance,
    and zero crawler barriers.
    """
    hp = Path(headers_path)
    issues: List[str] = []

    if not hp.is_file():
        return {
            "status": "FAIL",
            "headers_path": str(hp),
            "violations_count": 1,
            "issues": [f"Headers file not found: {hp}"],
        }

    try:
        content = hp.read_text(encoding="utf-8")
    except Exception as e:
        return {
            "status": "FAIL",
            "headers_path": str(hp),
            "violations_count": 1,
            "issues": [f"Failed to read headers file: {e}"],
        }

    # Contract verification
    try:
        from pseofactory.contracts import assert_headers_snippet_policy
        assert_headers_snippet_policy(content, context=str(hp))
    except Exception as e:
        issues.append(f"Snippet policy violation: {e}")

    # Parse route headers
    route_headers: Dict[str, Dict[str, str]] = {}
    current_route = ""
    for raw_line in content.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if not raw_line.startswith(" ") and not raw_line.startswith("\t"):
            current_route = line
            if current_route not in route_headers:
                route_headers[current_route] = {}
        else:
            if ":" in line and current_route:
                k, v = line.split(":", 1)
                route_headers[current_route][k.strip().lower()] = v.strip()

    # 1. Check root route /* cache control
    root_hdrs = route_headers.get("/*", {})
    root_cc = root_hdrs.get("cache-control", "").lower()
    if not root_cc:
        issues.append("Missing Cache-Control header for root route '/*'")
    else:
        if "s-maxage=86400" not in root_cc:
            issues.append("Root route '/* missing s-maxage=86400 in Cache-Control")
        if "stale-while-revalidate=604800" not in root_cc:
            issues.append("Root route '/* missing stale-while-revalidate=604800 in Cache-Control")

    # 2. Check static assets have immutable
    static_routes = [r for r in route_headers if any(pat in r for pat in ["/static", "/css", "/js", "/assets"])]
    for sr in static_routes:
        cc = route_headers[sr].get("cache-control", "").lower()
        if "immutable" not in cc:
            issues.append(f"Static pattern '{sr}' missing 'immutable' directive in Cache-Control")

    # 3. Check machine endpoints declare RFC 5988 canonical link and UTF-8 charset
    machine_exts = (".xml", ".txt", ".json")
    for r, hdrs in route_headers.items():
        if any(r.endswith(ext) for ext in machine_exts):
            link = hdrs.get("link", "")
            if 'rel="canonical"' not in link and "rel='canonical'" not in link:
                issues.append(f"Machine endpoint '{r}' missing RFC 5988 canonical Link header")
            ct = hdrs.get("content-type", "")
            if "charset=utf-8" not in ct.lower():
                issues.append(f"Machine endpoint '{r}' missing UTF-8 charset in Content-Type")

    # 4. Check for lethal crawler barriers on public routes
    for r, hdrs in route_headers.items():
        if r.startswith(("/signal", "/staging", "/test")):
            continue
        x_robots = hdrs.get("x-robots-tag", "").lower()
        if "noindex" in x_robots:
            issues.append(f"Public route '{r}' has lethal noindex directive")
        if "nosnippet" in x_robots:
            issues.append(f"Public route '{r}' has lethal nosnippet directive")
        if "max-snippet:0" in x_robots:
            issues.append(f"Public route '{r}' has lethal max-snippet:0 directive")

    if enforce_rule_cap and len(route_headers) > 100:
        issues.append(
            f"Cloudflare Pages _headers 100-rule limit exceeded: {len(route_headers)} active rules (max 100)"
        )

    return {
        "status": "PASS" if not issues else "FAIL",
        "headers_path": str(hp),
        "active_rules_count": len(route_headers),
        "cloudflare_rule_cap_compliant": len(route_headers) <= 100,
        "violations_count": len(issues),
        "issues": issues,
    }


class RejectOrNoiseStr(str):
    """String subclass that compares equal to both 'noise' and 'REJECT'."""

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, str) and other in ("noise", "REJECT", "reject", "Noise"):
            return True
        return super().__eq__(other)

    def __hash__(self) -> int:
        return hash("noise")


@dataclass
class VisitorIntent:
    """Classified search intent of a visiting edge request."""

    query: str
    target_asset_type: Union[str, RejectOrNoiseStr]
    intent_weight: float
    intent_cluster: str
    action: str = "ALLOW"
    is_noise: bool = False
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "query": self.query,
            "target_asset_type": str(self.target_asset_type),
            "intent_weight": self.intent_weight,
            "intent_cluster": self.intent_cluster,
            "action": self.action,
            "is_noise": self.is_noise,
            "metadata": self.metadata,
        }

    def __getitem__(self, item: str) -> Any:
        return getattr(self, item)


@dataclass
class RouteDecision:
    """Edge routing decision for incoming visitor query and current path."""

    action: str  # REWRITE_TO_CLUSTER, INJECT_OVERLAY, PASS_THROUGH
    target_path: str
    reason: str
    intent: Optional[VisitorIntent] = None
    overlay_keyword: Optional[str] = None
    matched_cluster: Optional[str] = None
    status_code: int = 200
    headers: Dict[str, str] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "action": self.action,
            "target_path": self.target_path,
            "reason": self.reason,
            "intent": self.intent.to_dict() if self.intent else None,
            "overlay_keyword": self.overlay_keyword,
            "matched_cluster": self.matched_cluster,
            "status_code": self.status_code,
            "headers": self.headers,
        }

    def __getitem__(self, item: str) -> Any:
        return getattr(self, item)


class EdgeVisitorClassifier:
    """
    Sub-millisecond Edge Visitor Search Intent Classifier.
    Extracts search queries from Referer headers or URL parameters,
    and categorizes visitors into Search Intent Doctrine asset archetypes.
    Zero em-dashes. Zero en-dashes.
    """

    SEARCH_ENGINE_HOSTS: Set[str] = {
        "google.com",
        "www.google.com",
        "bing.com",
        "www.bing.com",
        "duckduckgo.com",
        "www.duckduckgo.com",
    }

    @classmethod
    def extract_search_query(
        cls,
        headers: Optional[Dict[str, str]] = None,
        url: Optional[str] = None,
        referer: Optional[str] = None,
    ) -> Optional[str]:
        """
        Extracts search query from Referer headers (Google, Bing, DuckDuckGo)
        or URL parameters (?q=, ?s=, ?query=).
        Returns None if no search query is found.
        """
        # 1. Check URL parameters first (?q=, ?s=, ?query=)
        if url:
            url_str = str(url).strip()
            if url_str:
                query_string = (
                    url_str.split("?", 1)[1]
                    if "?" in url_str
                    else (url_str if url_str.startswith("?") else "")
                )
                if query_string:
                    qs = urllib.parse.parse_qs(query_string, keep_blank_values=False)
                    for param in ("q", "s", "query"):
                        for k, v_list in qs.items():
                            if k.lower() == param and v_list:
                                val = urllib.parse.unquote_plus(v_list[0]).strip()
                                if val:
                                    assert_no_forbidden_dashes(val, "EdgeVisitorClassifier.extract_search_query.url")
                                    return val

        # 2. Check Referer header (either explicit or from headers dict)
        ref_candidate = referer
        if not ref_candidate and headers:
            for k, v in headers.items():
                if k.lower() in ("referer", "referrer"):
                    ref_candidate = v
                    break

        if ref_candidate:
            ref_str = str(ref_candidate).strip()
            if ref_str:
                try:
                    parsed = urllib.parse.urlparse(ref_str)
                    host = parsed.netloc.lower()
                    qs = urllib.parse.parse_qs(parsed.query, keep_blank_values=False)
                    for param in ("q", "query", "s", "p"):
                        for k, v_list in qs.items():
                            if k.lower() == param and v_list:
                                val = urllib.parse.unquote_plus(v_list[0]).strip()
                                if val:
                                    assert_no_forbidden_dashes(val, "EdgeVisitorClassifier.extract_search_query.referer")
                                    return val
                except Exception:
                    pass

        return None

    def extract_query(
        self,
        headers: Optional[Dict[str, str]] = None,
        url: Optional[str] = None,
        referer: Optional[str] = None,
    ) -> Optional[str]:
        """Instance alias for extract_search_query."""
        return self.extract_search_query(headers=headers, url=url, referer=referer)

    @classmethod
    def classify(
        cls,
        query: str,
        intent_cluster: Optional[str] = None,
    ) -> VisitorIntent:
        """
        Classifies visitor intent aligned with calculate_intent_weight and
        determine_target_asset_type in pseofactory/trends/jev_engine.py:
        * Statutory calculations / deductions -> interactive_calculator (intent_weight 1.0)
        * Statutory matrices / rules -> statutory_matrix (intent_weight 1.0)
        * Competitor / product comparisons -> comparison_engine (intent_weight 0.7)
        * General tools -> interactive_calculator (intent_weight 0.8)
        * Noise / memes -> REJECT / noise (intent_weight 0.05)
        * Informational -> void_documentation (intent_weight 0.3)
        """
        clean_q = (query or "").strip()
        assert_no_forbidden_dashes(clean_q, "EdgeVisitorClassifier.classify")
        q_low = clean_q.lower()
        cluster = (intent_cluster or "").lower()

        # Archetype 1: Noise / memes -> REJECT / noise (intent_weight 0.05)
        noise_keywords = [
            "meme", "remix", "soundboard", "dress", "gossip",
            "scrubbed", "leak", "noise", "funny", "prank", "parody",
        ]
        if cluster == "noise" or any(w in q_low for w in noise_keywords):
            return VisitorIntent(
                query=clean_q,
                target_asset_type=RejectOrNoiseStr("noise"),
                intent_weight=0.05,
                intent_cluster="noise",
                action="REJECT",
                is_noise=True,
            )

        # Archetype 2: Statutory calculations / deductions -> interactive_calculator (intent_weight 1.0)
        is_statutory_calc = False
        if any(w in q_low for w in ["deduction", "deductions", "statutory calculation", "statutory calc"]):
            is_statutory_calc = True
        elif any(w in q_low for w in ["calculator", "calc", "estimator"]) and any(
            w in q_low for w in ["statutory", "section", "tax", "irs", "form", "depreciation", "compliance"]
        ):
            is_statutory_calc = True
        elif cluster in ("calculator", "statutory_compliance") and any(
            w in q_low for w in ["deduction", "section", "tax", "calc", "calculator", "estimator"]
        ):
            if not ("matrix" in q_low or "rule" in q_low or "rules" in q_low):
                is_statutory_calc = True

        if is_statutory_calc:
            return VisitorIntent(
                query=clean_q,
                target_asset_type="interactive_calculator",
                intent_weight=1.0,
                intent_cluster="calculator" if cluster == "calculator" else "statutory_compliance",
                action="ALLOW",
                is_noise=False,
            )

        # Archetype 3: Statutory matrices / rules -> statutory_matrix (intent_weight 1.0)
        is_statutory_matrix = False
        if "matrix" in q_low or "statutory matrix" in q_low:
            is_statutory_matrix = True
        elif "statutory" in q_low and any(w in q_low for w in ["rule", "rules", "matrix", "compliance", "standard", "table"]):
            is_statutory_matrix = True
        elif cluster == "statutory_compliance" or "statutory" in q_low:
            is_statutory_matrix = True

        if is_statutory_matrix:
            return VisitorIntent(
                query=clean_q,
                target_asset_type="statutory_matrix",
                intent_weight=1.0,
                intent_cluster="statutory_compliance",
                action="ALLOW",
                is_noise=False,
            )

        # Archetype 4: Competitor / product comparisons -> comparison_engine (intent_weight 0.7)
        is_comparison = False
        if cluster == "comparison":
            is_comparison = True
        elif any(w in q_low for w in ["versus", "compare", "comparison", "alternative", "competitor"]):
            is_comparison = True
        elif re.search(r"\bvs\b", q_low):
            is_comparison = True

        if is_comparison:
            return VisitorIntent(
                query=clean_q,
                target_asset_type="comparison_engine",
                intent_weight=0.7,
                intent_cluster="comparison",
                action="ALLOW",
                is_noise=False,
            )

        # Archetype 5: General tools -> interactive_calculator (intent_weight 0.8)
        is_tool = False
        if cluster == "tool" or any(w in q_low for w in ["tool", "tools", "generator", "builder", "converter"]):
            is_tool = True
        elif cluster == "calculator" or any(w in q_low for w in ["calculator", "calc", "estimator"]):
            return VisitorIntent(
                query=clean_q,
                target_asset_type="interactive_calculator",
                intent_weight=1.0 if cluster == "calculator" or "calculator" in q_low else 0.8,
                intent_cluster="calculator",
                action="ALLOW",
                is_noise=False,
            )

        if is_tool:
            return VisitorIntent(
                query=clean_q,
                target_asset_type="interactive_calculator",
                intent_weight=0.8,
                intent_cluster="tool",
                action="ALLOW",
                is_noise=False,
            )

        # Archetype 6: Informational -> void_documentation (intent_weight 0.3)
        return VisitorIntent(
            query=clean_q,
            target_asset_type="void_documentation",
            intent_weight=0.3,
            intent_cluster="informational",
            action="ALLOW",
            is_noise=False,
        )

    def classify_intent(
        self,
        query: str,
        intent_cluster: Optional[str] = None,
    ) -> VisitorIntent:
        """Instance alias for classify."""
        return self.classify(query, intent_cluster=intent_cluster)


class EdgeIntentRouter:
    """
    Sub-millisecond Edge Intent Router.
    Decides routing actions:
    - REWRITE_TO_CLUSTER when visitor query matches a high-yield cluster different from current path
    - INJECT_OVERLAY when visitor query matches striking-distance keyword on current page
    - PASS_THROUGH when no intent mismatch exists
    Zero em-dashes. Zero en-dashes.
    """

    def __init__(
        self,
        routes_map: Optional[Dict[str, Any]] = None,
        striking_distance_map: Optional[Dict[str, List[str]]] = None,
        classifier: Optional[EdgeVisitorClassifier] = None,
    ):
        self.routes_map = routes_map or {}
        self.striking_distance_map = striking_distance_map or {}
        self.classifier = classifier or EdgeVisitorClassifier()

    def route(
        self,
        current_path: str,
        query: Optional[str] = None,
        headers: Optional[Dict[str, str]] = None,
        url: Optional[str] = None,
        referer: Optional[str] = None,
        striking_keywords: Optional[List[str]] = None,
    ) -> RouteDecision:
        """
        Determines edge routing decision for request.
        """
        assert_no_forbidden_dashes(current_path, "EdgeIntentRouter.route.current_path")

        # 1. Resolve query
        extracted_q = query
        if extracted_q is None:
            extracted_q = self.classifier.extract_search_query(headers=headers, url=url, referer=referer)

        if not extracted_q:
            return RouteDecision(
                action="PASS_THROUGH",
                target_path=current_path,
                reason="No search query detected; pass through",
            )

        assert_no_forbidden_dashes(extracted_q, "EdgeIntentRouter.route.query")

        # 2. Classify intent
        intent = self.classifier.classify(extracted_q)

        # Noise / memes pass through without rewrites or overlays
        if intent.is_noise:
            return RouteDecision(
                action="PASS_THROUGH",
                target_path=current_path,
                reason=f"Noise query '{extracted_q}' rejected; pass through",
                intent=intent,
            )

        # 3. Check INJECT_OVERLAY (striking distance match on current page)
        current_normalized = current_path.rstrip("/")
        page_striking: List[str] = []
        if striking_keywords:
            page_striking.extend(striking_keywords)

        for p, kw_list in self.striking_distance_map.items():
            if p.rstrip("/") == current_normalized:
                page_striking.extend(kw_list)

        for p, meta in self.routes_map.items():
            if isinstance(meta, dict) and p.rstrip("/") == current_normalized:
                page_striking.extend(meta.get("striking_distance", []))

        q_low = extracted_q.lower()
        for kw in page_striking:
            kw_low = kw.lower()
            if kw_low in q_low or q_low in kw_low or set(kw_low.split()).issubset(set(q_low.split())):
                return RouteDecision(
                    action="INJECT_OVERLAY",
                    target_path=current_path,
                    reason=f"Visitor query '{extracted_q}' matches striking-distance keyword '{kw}' on current page",
                    intent=intent,
                    overlay_keyword=kw,
                )

        # 4. Check REWRITE_TO_CLUSTER
        # High-yield clusters have intent_weight >= 0.7
        if intent.intent_weight >= 0.7:
            target_destination = self._find_cluster_destination(intent, extracted_q)
            if target_destination:
                target_normalized = target_destination.rstrip("/")
                if target_normalized != current_normalized:
                    return RouteDecision(
                        action="REWRITE_TO_CLUSTER",
                        target_path=target_destination,
                        reason=f"High-yield intent '{intent.target_asset_type}' mismatch: rewrite from '{current_path}' to '{target_destination}'",
                        intent=intent,
                        matched_cluster=str(intent.target_asset_type),
                    )

        # 5. Default PASS_THROUGH
        return RouteDecision(
            action="PASS_THROUGH",
            target_path=current_path,
            reason="No intent mismatch exists; pass through",
            intent=intent,
        )

    def _find_cluster_destination(self, intent: VisitorIntent, query: str) -> Optional[str]:
        """Finds matching cluster destination path from routes_map."""
        q_low = query.lower()

        # Check direct key in routes_map for target asset type or cluster
        for key in (str(intent.target_asset_type), intent.intent_cluster):
            if key in self.routes_map and isinstance(self.routes_map[key], str):
                return self.routes_map[key]

        # Check structured routes_map (path -> metadata)
        for path_key, val in self.routes_map.items():
            if isinstance(val, dict):
                # Check target_asset_type match
                if val.get("target_asset_type") == str(intent.target_asset_type):
                    kws = val.get("keywords", [])
                    if not kws or any(kw.lower() in q_low or q_low in kw.lower() for kw in kws):
                        return path_key
                # Check cluster match
                elif val.get("cluster") == intent.intent_cluster:
                    kws = val.get("keywords", [])
                    if not kws or any(kw.lower() in q_low or q_low in kw.lower() for kw in kws):
                        return path_key

        return None


def generate_edge_worker_script(routes_map: Optional[Dict[str, Any]] = None) -> str:
    """
    Generates a production Cloudflare Worker JavaScript snippet implementing
    sub-millisecond edge classification, Referer / URL parameter extraction,
    and routing decisions (REWRITE_TO_CLUSTER, INJECT_OVERLAY, PASS_THROUGH).
    Zero em-dashes. Zero en-dashes.
    """
    routes_json = json.dumps(routes_map or {}, indent=2)

    script = f"""/**
 * Cloudflare Worker: Dynamic Edge Search Intent Router
 * Generated by pseofactory.edge
 * Sub-millisecond edge classification and dynamic search intent routing.
 * Zero em-dashes. Zero en-dashes.
 */

const ROUTES_MAP = {routes_json};

function extractSearchQuery(request) {{
  const url = new URL(request.url);

  // 1. Check URL parameters (?q=, ?s=, ?query=)
  for (const param of ["q", "s", "query"]) {{
    const val = url.searchParams.get(param);
    if (val && val.trim().length > 0) {{
      return decodeURIComponent(val.trim().replace(/\\+/g, " "));
    }}
  }}

  // 2. Check Referer header (Google, Bing, DuckDuckGo)
  const referer = request.headers.get("referer") || request.headers.get("referrer") || "";
  if (referer) {{
    try {{
      const refUrl = new URL(referer);
      const host = refUrl.hostname.toLowerCase();
      if (host.includes("google.") || host.includes("bing.") || host.includes("duckduckgo.")) {{
        for (const param of ["q", "query", "s", "p"]) {{
          const val = refUrl.searchParams.get(param);
          if (val && val.trim().length > 0) {{
            return decodeURIComponent(val.trim().replace(/\\+/g, " "));
          }}
        }}
      }}
    }} catch (e) {{
      // Invalid referer URL format; ignore
    }}
  }}

  return null;
}}

function classifyVisitorIntent(query) {{
  if (!query) {{
    return {{
      query: "",
      target_asset_type: "void_documentation",
      intent_weight: 0.3,
      intent_cluster: "informational",
      action: "ALLOW",
      is_noise: false
    }};
  }}

  const q = query.toLowerCase();

  // Noise / memes -> REJECT / noise (intent_weight 0.05)
  const noiseTerms = ["meme", "remix", "soundboard", "dress", "gossip", "scrubbed", "leak", "noise", "funny", "prank", "parody"];
  if (noiseTerms.some(term => q.includes(term))) {{
    return {{
      query: query,
      target_asset_type: "noise",
      intent_weight: 0.05,
      intent_cluster: "noise",
      action: "REJECT",
      is_noise: true
    }};
  }}

  // Statutory calculations / deductions -> interactive_calculator (intent_weight 1.0)
  const isDeduction = q.includes("deduction") || q.includes("statutory calculation");
  const isStatutoryCalc = (q.includes("calculator") || q.includes("calc") || q.includes("estimator")) &&
    (q.includes("statutory") || q.includes("section") || q.includes("tax") || q.includes("irs") || q.includes("compliance") || q.includes("depreciation"));
  if (isDeduction || isStatutoryCalc) {{
    return {{
      query: query,
      target_asset_type: "interactive_calculator",
      intent_weight: 1.0,
      intent_cluster: "calculator",
      action: "ALLOW",
      is_noise: false
    }};
  }}

  // Statutory matrices / rules -> statutory_matrix (intent_weight 1.0)
  if (q.includes("matrix") || q.includes("statutory") || q.includes("rule") || q.includes("rules")) {{
    return {{
      query: query,
      target_asset_type: "statutory_matrix",
      intent_weight: 1.0,
      intent_cluster: "statutory_compliance",
      action: "ALLOW",
      is_noise: false
    }};
  }}

  // Competitor / product comparisons -> comparison_engine (intent_weight 0.7)
  if (/\\bvs\\b/.test(q) || q.includes("versus") || q.includes("compare") || q.includes("comparison") || q.includes("alternative")) {{
    return {{
      query: query,
      target_asset_type: "comparison_engine",
      intent_weight: 0.7,
      intent_cluster: "comparison",
      action: "ALLOW",
      is_noise: false
    }};
  }}

  // General tools -> interactive_calculator (intent_weight 0.8)
  if (q.includes("tool") || q.includes("generator") || q.includes("builder") || q.includes("calculator") || q.includes("calc") || q.includes("estimator")) {{
    const weight = (q.includes("calculator") || q.includes("calc") || q.includes("estimator")) ? 1.0 : 0.8;
    return {{
      query: query,
      target_asset_type: "interactive_calculator",
      intent_weight: weight,
      intent_cluster: "tool",
      action: "ALLOW",
      is_noise: false
    }};
  }}

  // Informational -> void_documentation (intent_weight 0.3)
  return {{
    query: query,
    target_asset_type: "void_documentation",
    intent_weight: 0.3,
    intent_cluster: "informational",
    action: "ALLOW",
    is_noise: false
  }};
}}

function determineEdgeRoute(request, routesMap) {{
  const url = new URL(request.url);
  const currentPath = url.pathname.replace(/\\/+$/, "") || "/";
  const query = extractSearchQuery(request);

  if (!query) {{
    return {{ action: "PASS_THROUGH", target_path: currentPath, reason: "No search query detected" }};
  }}

  const intent = classifyVisitorIntent(query);
  if (intent.is_noise) {{
    return {{ action: "PASS_THROUGH", target_path: currentPath, reason: "Noise query rejected", intent }};
  }}

  // 1. Check INJECT_OVERLAY (striking-distance match on current page)
  for (const [pathKey, config] of Object.entries(routesMap)) {{
    const normKey = pathKey.replace(/\\/+$/, "") || "/";
    if (normKey === currentPath && typeof config === "object" && Array.isArray(config.striking_distance)) {{
      const qLow = query.toLowerCase();
      for (const kw of config.striking_distance) {{
        if (qLow.includes(kw.toLowerCase()) || kw.toLowerCase().includes(qLow)) {{
          return {{
            action: "INJECT_OVERLAY",
            target_path: currentPath,
            overlay_keyword: kw,
            reason: `Query matched striking-distance keyword: ${{kw}}`,
            intent
          }};
        }}
      }}
    }}
  }}

  // 2. Check REWRITE_TO_CLUSTER (high-yield intent mismatch)
  if (intent.intent_weight >= 0.7) {{
    let targetPath = null;
    if (typeof routesMap[intent.target_asset_type] === "string") {{
      targetPath = routesMap[intent.target_asset_type];
    }} else {{
      for (const [pathKey, config] of Object.entries(routesMap)) {{
        if (typeof config === "object" && config.target_asset_type === intent.target_asset_type) {{
          targetPath = pathKey;
          break;
        }}
      }}
    }}

    if (targetPath) {{
      const normTarget = targetPath.replace(/\\/+$/, "") || "/";
      if (normTarget !== currentPath) {{
        return {{
          action: "REWRITE_TO_CLUSTER",
          target_path: targetPath,
          reason: `High-yield intent mismatch (${{intent.target_asset_type}})`,
          intent
        }};
      }}
    }}
  }}

  return {{ action: "PASS_THROUGH", target_path: currentPath, reason: "No intent mismatch exists", intent }};
}}

export {{ extractSearchQuery, classifyVisitorIntent, determineEdgeRoute }};

export default {{
  async fetch(request, env, ctx) {{
    const route = determineEdgeRoute(request, ROUTES_MAP);
    const url = new URL(request.url);

    if (route.action === "REWRITE_TO_CLUSTER" && route.target_path) {{
      const destinationUrl = new URL(route.target_path, url.origin);
      const modifiedRequest = new Request(destinationUrl, request);
      const response = await fetch(modifiedRequest);
      const newHeaders = new Headers(response.headers);
      newHeaders.set("X-Edge-Intent-Action", "REWRITE_TO_CLUSTER");
      newHeaders.set("X-Edge-Target-Path", route.target_path);
      return new Response(response.body, {{
        status: response.status,
        statusText: response.statusText,
        headers: newHeaders
      }});
    }}

    if (route.action === "INJECT_OVERLAY") {{
      const response = await fetch(request);
      const newHeaders = new Headers(response.headers);
      newHeaders.set("X-Edge-Intent-Action", "INJECT_OVERLAY");
      if (route.overlay_keyword) {{
        newHeaders.set("X-Edge-Overlay-Keyword", route.overlay_keyword);
      }}
      return new Response(response.body, {{
        status: response.status,
        statusText: response.statusText,
        headers: newHeaders
      }});
    }}

    const response = await fetch(request);
    const newHeaders = new Headers(response.headers);
    newHeaders.set("X-Edge-Intent-Action", "PASS_THROUGH");
    return new Response(response.body, {{
      status: response.status,
      statusText: response.statusText,
      headers: newHeaders
    }});
  }}
}};
"""
    assert_no_forbidden_dashes(script, "generate_edge_worker_script")
    return script


def _render_gainhelm_framework_routing_js(include_deliverables: bool = False) -> str:
    """
    Emits shared GainHelm framework classification and partner routing/desk JS
    derived from canonical Python GAINHELM_FRAMEWORK_PROFILES so /r/:partner
    redirects, /api/lead-capture, and Stripe checkout agree 100% across all 15 frameworks.
    Zero em-dashes. Zero en-dashes.
    """
    from pseofactory.affiliates import (
        GAINHELM_FRAMEWORK_PROFILES,
        GAINHELM_PARTNER_ALIASES,
        GAINHELM_PARTNER_REP_DESK_BY_KEY,
        GAINHELM_VANTA_URLS_BY_FRAMEWORK,
    )

    vanta_map_json = json.dumps(GAINHELM_VANTA_URLS_BY_FRAMEWORK, indent=2)
    default_slug_json = json.dumps(
        {k: str(v.get("default_sku_slug") or "soc-2-audit-cost-calculator") for k, v in GAINHELM_FRAMEWORK_PROFILES.items()},
        indent=2,
    )
    vertical_map_json = json.dumps(
        {k: str(v.get("vertical") or "soc2_grc_automation") for k, v in GAINHELM_FRAMEWORK_PROFILES.items()},
        indent=2,
    )
    primary_partner_json = json.dumps(
        {k: str(v.get("primary_partner_key") or "vanta_security") for k, v in GAINHELM_FRAMEWORK_PROFILES.items()},
        indent=2,
    )
    fw_desk_json = json.dumps(
        {k: str(v.get("partner_rep_desk") or GAINHELM_PARTNER_REP_DESK_BY_KEY["vanta_security"]) for k, v in GAINHELM_FRAMEWORK_PROFILES.items()},
        indent=2,
    )
    aliases_json = json.dumps(GAINHELM_PARTNER_ALIASES, indent=2)
    neutral_desk_json = json.dumps(GAINHELM_PARTNER_REP_DESK_BY_KEY, indent=2)
    deliverables_block = ""
    if include_deliverables:
        deliverables_json = json.dumps(
            {
                k: [str(d) for d in (v.get("deliverables") or ())]
                for k, v in GAINHELM_FRAMEWORK_PROFILES.items()
            },
            indent=2,
        )
        deliverables_block = f"const GAINHELM_DELIVERABLES_BY_FRAMEWORK = {deliverables_json};\n\n"
    return (
        f"const GAINHELM_VANTA_DESTINATION_MAP = {vanta_map_json};\n\n"
        f"const GAINHELM_DEFAULT_SLUG_BY_FRAMEWORK = {default_slug_json};\n\n"
        f"const GAINHELM_VERTICAL_BY_FRAMEWORK = {vertical_map_json};\n\n"
        f"const GAINHELM_PRIMARY_PARTNER_BY_FRAMEWORK = {primary_partner_json};\n\n"
        f"const GAINHELM_FRAMEWORK_DESK_BY_KEY = {fw_desk_json};\n\n"
        f"{deliverables_block}"
        f"const GAINHELM_PARTNER_ALIASES = {aliases_json};\n\n"
        f"const GAINHELM_PARTNER_REP_DESK_BY_KEY = {neutral_desk_json};\n\n"
        "const GAINHELM_VALID_VERTICALS = new Set(Object.values(GAINHELM_VERTICAL_BY_FRAMEWORK));\n\n"
        "function isGenericGainHelmToolSlug(toolSlug) {\n"
        '  const norm = String(toolSlug || "").trim().toLowerCase().replace(/^\\/+|\\/+$/g, "").replace(/^tools(?:\\/|$)/, "");\n'
        '  return !norm || norm === "general" || norm === "index" || norm === "home" || norm === "homepage";\n'
        "}\n\n"
        "function isExplicitGainHelmVertical(rawVertical) {\n"
        '  const v = String(rawVertical || "").trim().toLowerCase();\n'
        '  if (!v || v === "general" || v === "informational_governance") return false;\n'
        "  if (GAINHELM_VALID_VERTICALS.has(v) || Object.prototype.hasOwnProperty.call(GAINHELM_DEFAULT_SLUG_BY_FRAMEWORK, v)) {\n"
        "    return true;\n"
        "  }\n"
        '  return classifyGainHelmFramework("", v) !== "soc2";\n'
        "}\n\n"
        "function classifyGainHelmFramework(toolSlug, vertical) {\n"
        '  const s = `${toolSlug || ""} ${vertical || ""}`.trim().toLowerCase().replace(/_/g, "-");\n'
        '  if (s.includes("dora") || s.includes("ict-third-party") || s.includes("2022/2554") || s.includes("2022-2554")) return "dora";\n'
        '  if (s.includes("eu-ai-act") || s.includes("eu ai act") || s.includes("2024/1689") || s.includes("2024-1689") || s.includes("article43") || s.includes("conformity-assessment")) return "eu_ai_act";\n'
        '  if (s.includes("sec-cybersecurity") || s.includes("8k-item-105") || s.includes("item-105") || s.includes("229.106") || s.includes("materiality-8k") || s.includes("sec-8k") || s.includes("sec-cyber-disclosure")) return "sec_8k";\n'
        '  if (s.includes("gdpr")) return "gdpr";\n'
        '  if (s.includes("ccpa") || s.includes("cpra")) return "ccpa";\n'
        '  if (s.includes("nis2") || s.includes("nis-2")) return "nis2";\n'
        '  if (s.includes("hipaa") || s.includes("hitech")) return "hipaa";\n'
        '  if (s.includes("iso-27001") || s.includes("iso27001") || s.includes("27001")) return "iso_27001";\n'
        '  if (s.includes("pci-dss") || s.includes("pci-") || s.includes("qsa")) return "pci_dss";\n'
        '  if (s.includes("hitrust")) return "hitrust";\n'
        '  if (s.includes("fedramp") || s.includes("stateramp") || s.includes("txramp")) return "fedramp";\n'
        '  if (s.includes("penetration-test") || s.includes("pentest") || s.includes("penetration")) return "pentest";\n'
        '  if (s.includes("cyber-liability") || s.includes("cyber-insurance") || s.includes("breach-exposure")) return "cyber_insurance";\n'
        '  if (s.includes("cmmc") || s.includes("sprs") || s.includes("800-171") || s.includes("federal-defense-grc")) return "cmmc";\n'
        '  return "soc2";\n'
        "}\n\n"
        "function resolveGainHelmPartnerRepDesk(partnerKey, fwKey) {\n"
        '  const pkRaw = String(partnerKey || "").trim().toLowerCase();\n'
        "  const pkNorm = GAINHELM_PARTNER_ALIASES[pkRaw] || pkRaw;\n"
        '  const fwPrimary = GAINHELM_PRIMARY_PARTNER_BY_FRAMEWORK[fwKey] || "vanta_security";\n'
        '  const fwDesk = GAINHELM_FRAMEWORK_DESK_BY_KEY[fwKey] || "Vanta Trust Management & SOC 2 Audit Desk";\n'
        "  if (!pkNorm || pkNorm === fwPrimary) {\n"
        "    return fwDesk;\n"
        "  }\n"
        "  return GAINHELM_PARTNER_REP_DESK_BY_KEY[pkNorm] || fwDesk;\n"
        "}\n\n"
        "function resolveVantaDestinationUrl(fwKey) {\n"
        '  return GAINHELM_VANTA_DESTINATION_MAP[fwKey] || GAINHELM_VANTA_DESTINATION_MAP.soc2 || "https://www.vanta.com/products/soc-2";\n'
        "}"
    )


def generate_edge_redirect_function(
    property_id: str = "profithelm",
    hub: Optional[Any] = None,
) -> str:
    """
    Generates the deterministic Cloudflare Pages Function (functions/r/[partner].js)
    for ProfitHelm or Prexvo outbound affiliate redirects from the canonical affiliate registry,
    verified Sovrn merchant coverage table, and monetization vault.
    Zero em-dashes. Zero en-dashes.
    """
    from pseofactory.affiliates import (
        PROFITHELM_AFFILIATES,
        PREXVO_AFFILIATES,
        GAINHELM_AFFILIATES,
        LIENBOND_AFFILIATES,
        SOVRN_VERIFIED_PAYING_MERCHANTS,
    )
    from pseofactory.affiliates_hub import MonetizationHub

    prop_clean = (property_id or "").strip().lower()
    if prop_clean not in ("profithelm", "prexvo", "gainhelm", "lienbond"):
        raise ValueError(
            f"Edge redirect function generation is only supported for profithelm, prexvo, gainhelm, or lienbond (got '{property_id}')."
        )

    active_hub = hub if hub is not None else MonetizationHub()

    if prop_clean == "lienbond":
        lb_vault = getattr(active_hub, "_vault", {}).get("lienbond", {}) if active_hub else {}
        lb_direct_upgrades: Dict[str, str] = {}
        if hasattr(active_hub, "get_direct_contract_upgrades"):
            lb_direct_upgrades.update(active_hub.get_direct_contract_upgrades("lienbond"))
        _lb_declined = {"declined", "rejected", "terminated", "revoked", "expired", "suspended", "inactive"}
        _lb_live = {"live", "active_direct", "approved", "active"}
        _lb_pending = {"pending", "pending_p2", "in_review", "awaiting_response"}

        def _lb_state(k_name: str, canon_k: str, base_st: str) -> Tuple[str, bool, str]:
            ve = (
                lb_vault.get(k_name)
                if isinstance(lb_vault, dict) and isinstance(lb_vault.get(k_name), dict)
                else (lb_vault.get(canon_k) if isinstance(lb_vault, dict) else None)
            )
            vst = str(ve.get("status") or "").strip().lower() if isinstance(ve, dict) else ""
            if vst in _lb_declined or (base_st == "declined" and vst not in _lb_live and vst not in _lb_pending):
                return ("declined", False, "")
            if vst in _lb_live or (base_st == "live" and vst not in _lb_pending):
                vu = str(ve.get("approved_tracking_url") or ve.get("url") or ve.get("direct_url") or "").strip() if isinstance(ve, dict) else ""
                cu = lb_direct_upgrades.get(k_name) or lb_direct_upgrades.get(canon_k) or (vu if vu and is_intent_matched(canon_k, vu) else "")
                return ("live", True, cu)
            return ("pending_p2" if vst == "pending_p2" else "pending", False, "")

        lienbond_catalog_entries: List[str] = []
        for k, p_obj in LIENBOND_AFFILIATES.items():
            status_val, lb_is_direct, direct_contract_url = _lb_state(k, p_obj.key, p_obj.status or "pending")
            status_env = p_obj.env_var[:-4] + "_STATUS" if p_obj.env_var.endswith("_URL") else f"AFFILIATE_{k.upper()}_STATUS"
            extra_contract_line = f'    directContractUrl: "{direct_contract_url}",\n' if direct_contract_url else ""
            lienbond_catalog_entries.append(
                f'  {k}: {{\n'
                f'    defaultUrl: "{p_obj.default_url}",\n'
                f'{extra_contract_line}'
                f'    envVar: "{p_obj.env_var}",\n'
                f'    statusEnvVar: "{status_env}",\n'
                f'    status: "{status_val}",\n'
                f'    isDirect: {"true" if lb_is_direct else "false"},\n'
                f'  }},'
            )
        lienbond_aliases = {
            "surety_bonds": (
                "https://www.suretybondsdirect.com/",
                "AFFILIATE_SURETYBONDS_DIRECT_URL",
                "AFFILIATE_SURETYBONDS_DIRECT_STATUS",
                "suretybonds_direct",
            ),
            "next_insurance": (
                "https://www.nextinsurance.com/",
                "AFFILIATE_NEXT_INSURANCE_URL",
                "AFFILIATE_NEXT_INSURANCE_STATUS",
                "next_insurance_b2b",
            ),
            "thimble": (
                "https://www.thimble.com/",
                "AFFILIATE_THIMBLE_CONTRACTOR_URL",
                "AFFILIATE_THIMBLE_CONTRACTOR_STATUS",
                "thimble_contractor",
            ),
            "jobber": (
                "https://getjobber.com/",
                "AFFILIATE_JOBBER_FIELD_SERVICE_URL",
                "AFFILIATE_JOBBER_FIELD_SERVICE_STATUS",
                "jobber_field_service",
            ),
            "levelset": (
                "https://www.levelset.com/",
                "AFFILIATE_LEVELSET_LIEN_FILING_URL",
                "AFFILIATE_LEVELSET_LIEN_FILING_STATUS",
                "levelset_lien_filing",
            ),
        }
